# ---------------------------------------------------------------- 解析

def _num(s):
    try:
        return float(str(s).strip())
    except Exception:
        return None


def _split_units(header):
    cols, units = [], []
    for tok in header.split(","):
        tok = tok.strip()
        if "/" in tok:
            name, unit = tok.rsplit("/", 1)
            cols.append(name.strip())
            units.append(unit.strip())
        else:
            cols.append(tok)
            units.append("")
    return cols, units


def parse_chi(text):
    """CHI 文本 → dataset dict；找不到列头返回 None。"""
    lines = text.splitlines()
    meta = {"date": lines[0].strip() if lines else "",
            "technique": lines[1].strip() if len(lines) > 1 else "",
            "instrument": ""}
    params = {}
    header_i = None
    for i, ln in enumerate(lines):
        s = ln.strip()
        if s.startswith("Instrument Model:"):
            meta["instrument"] = s.split(":", 1)[1].strip()
        m = re.match(r"^([A-Za-z][\w ()\-/\[\]]*?)\s*=\s*(.+)$", s)
        if m and "Instrument" not in s:
            params[m.group(1).strip()] = m.group(2).strip()
        if "," in s and re.search(r"/\s*[A-Za-zΩ%°]", s) and not s[0].isdigit():
            header_i = i
            break
    if header_i is None:
        return None
    cols, units = _split_units(lines[header_i])
    rows = []
    for ln in lines[header_i + 1:]:
        parts = [p.strip() for p in ln.split(",")]
        if len(parts) != len(cols):
            continue
        vals = [_num(p) for p in parts]
        if any(v is None for v in vals):
            continue
        rows.append(vals)
    if not rows:
        return None
    return {"format": "chi", "columns": cols, "units": units,
            "rows": rows, "meta": meta, "params": params}


def parse_digisim(text):
    lines = text.splitlines()
    meta = {"date": "", "technique": "CV (DIGISIM)", "instrument": "DIGISIM"}
    params = {}
    for ln in lines:
        m = re.match(r"^([A-Za-z][^:=]*?):\s*(.+)$", ln)
        if m:
            params[m.group(1).strip()] = m.group(2).strip()
    start = None
    for i, ln in enumerate(lines):
        if re.search(r"couples", ln):
            start = i + 1
            break
    if start is None:
        return None
    rows = []
    for ln in lines[start:]:
        parts = [p.strip() for p in ln.split(",")]
        if len(parts) != 2:
            continue
        vals = [_num(p) for p in parts]
        if any(v is None for v in vals):
            continue
        rows.append(vals)
    if not rows:
        return None
    return {"format": "digisim", "columns": ["E", "I"], "units": ["V", "A"],
            "rows": rows, "meta": meta, "params": params}


def parse_csv(text):
    if text.startswith("\ufeff"):
        text = text[1:]
    rd = csv.reader(io.StringIO(text))
    rows = [r for r in rd if any(str(c).strip() for c in r)]
    if len(rows) < 2:
        return None
    header = [str(c).strip() for c in rows[0]]
    raw = [[str(c).strip() for c in r] for r in rows[1:]]
    ncol = min(len(header), min(len(r) for r in raw))
    # 只保留数值列：结果表常混有文本列（False / 路径 / 单位名），不能因此弃整行
    keep = []
    for j in range(ncol):
        hit = sum(1 for r in raw if _num(r[j]) is not None)
        if hit >= max(1, len(raw) // 2):
            keep.append(j)
    if not keep:
        return None
    data = []
    for r in raw:
        vals = [_num(r[j]) for j in keep]
        if any(v is None for v in vals):
            continue
        data.append(vals)
    if not data:
        return None
    return {"format": "csv", "columns": [header[j] for j in keep],
            "units": [""] * len(keep), "rows": data,
            "meta": {"date": "", "technique": "CSV", "instrument": ""},
            "params": {}}


def detect_format(path):
    ext = os.path.splitext(path)[1].lower()
    if ext in UNSUPPORTED_EXT:
        return "unsupported"
    with open(path, "rb") as f:
        raw = f.read(4096)
    text = raw.decode("utf-8", "replace")
    if ext == ".csv":
        return "csv"
    if "Instrument Model:" in text or re.search(r",\s*[\w'\"()/]+\s*/", text):
        return "chi"
    if re.search(r"couples", text):
        return "digisim"
    return "unknown"


def read_dataset(path):
    fmt = detect_format(path)
    if fmt == "unsupported":
        raise SystemExit(f"[!] 不支持的格式：{path}（当前支持 chi / digisim / csv）")
    if fmt == "csv":
        text = open(path, "rb").read().decode("utf-8-sig", "replace")
        d = parse_csv(text)
    else:
        text = open(path, "rb").read().decode("utf-8", "replace")
        d = parse_chi(text) or parse_digisim(text)
    if not d:
        raise SystemExit(f"[!] 解析失败：{path}")
    d["path"] = os.path.abspath(path)
    return d


# ---------------------------------------------------------------- 统计

def analyze(d):
    rows = d["rows"]
    cols, units = d["columns"], d["units"]
    stats = {"n_points": len(rows), "n_columns": len(cols), "columns": []}
    for j, (c, u) in enumerate(zip(cols, units)):
        xs = [r[j] for r in rows]
        mn, mx = min(xs), max(xs)
        stats["columns"].append({"name": c, "unit": u, "min": mn, "max": mx,
                                 "mean": statistics.fmean(xs)})
    # x 轴步长与单调段（CV 用）
    if len(rows) > 2:
        x = [r[0] for r in rows]
        dx = [x[i + 1] - x[i] for i in range(len(x) - 1)]
        nz = [d_ for d_ in dx if abs(d_) > 1e-12]
        stats["x_step_median"] = statistics.median(nz) if nz else 0.0
        segs, cur = 1, (1 if (dx and dx[0] > 0) else -1)
        for d_ in dx:
            if d_ * cur < 0:
                segs += 1
                cur = -cur
        stats["x_segments"] = segs
    # 质量标记
    flags = []
    if len(rows) < 10:
        flags.append("点数过少(<10)")
    x = [r[0] for r in rows]
    if len(set(x)) < len(x):
        flags.append("x 有重复值")
    if any(abs(r[0]) > 1e6 for r in rows):
        flags.append("x 出现异常大值")
    stats["flags"] = flags
    return stats


