def export_processed(d, out_dir):
    os.makedirs(out_dir, exist_ok=True)
    stem = os.path.splitext(os.path.basename(d["path"]))[0]
    p_csv = os.path.join(out_dir, stem + "_processed.csv")
    with open(p_csv, "w", encoding="utf-8", newline="") as f:
        w = csv.writer(f)
        w.writerow([f"{c}/{u}" if u else c for c, u in zip(d["columns"], d["units"])])
        for r in d["rows"]:
            w.writerow([repr(v) for v in r])
    p_meta = os.path.join(out_dir, stem + "_meta.json")
    with open(p_meta, "w", encoding="utf-8", newline="\n") as f:
        json.dump({"source": d["path"], "format": d["format"],
                   "meta": d["meta"], "params": d["params"],
                   "columns": d["columns"], "units": d["units"],
                   "n_points": len(d["rows"]),
                   "exported": datetime.datetime.now().isoformat(timespec="seconds")},
                  f, ensure_ascii=False, indent=2)
        f.write("\n")
    return p_csv, p_meta


def currents_at(rows, e0, tol):
    return [r[1] for r in rows if abs(r[0] - e0) <= tol]


def ecsa_from_scans(scans, cs_uF_cm2=60.0, area=1.0, min_rates=3):
    """由不同扫速的 CV 在固定电位处的电流摆幅算 Cdl 与 ECSA。

    scans: [(scan_rate_V_s, [current_A, ...]), ...]；每个电流列表是 E0 附近的采样点。
    做法：Δj = max(j) − min(j)（正向/反向两支）→ Δj/2 对扫速线性拟合 →
    slope = Cdl（mF cm⁻²）；ECSA = Cdl / (Cs/1000)（cm²）；RF = ECSA / 几何面积。

    🔴 建议 #1：扫速数 < min_rates（默认 3）直接拒绝——单/双扫速时斜率不可靠，
       历史上曾把单点拟合出的机器零写进结果。
    """
    pts = []
    for nu, currents in scans:
        if not currents:
            continue
        dj = (max(currents) - min(currents)) * 1000.0 / float(area)   # mA cm⁻²
        pts.append((float(nu), dj / 2.0))
    if len(pts) < int(min_rates):
        raise SystemExit(f"[!] ECSA 至少需要 {min_rates} 个不同扫速（给到 {len(pts)} 个）；"
                         "少于 3 个时斜率不可靠，拒绝出数")
    return fit_ecsa_points(pts, cs_uF_cm2, area)


def fit_ecsa_points(pts, cs_uF_cm2=60.0, area=1.0):
    """pts: [(scan_rate_V_s, delta_j_half_mA_cm2), ...] → 拟合结果。"""
    if len(pts) < 2:
        raise SystemExit("[!] ECSA 拟合至少需要 2 个点")
    pts = sorted(pts)
    n = len(pts)
    sx = sum(p[0] for p in pts)
    sy = sum(p[1] for p in pts)
    sxx = sum(p[0] ** 2 for p in pts)
    sxy = sum(p[0] * p[1] for p in pts)
    slope = (n * sxy - sx * sy) / (n * sxx - sx * sx)
    inter = (sy - slope * sx) / n
    ss_tot = sum((p[1] - sy / n) ** 2 for p in pts)
    ss_res = sum((p[1] - (slope * p[0] + inter)) ** 2 for p in pts)
    r2 = 1 - ss_res / ss_tot if ss_tot else 0.0
    cdl = slope                      # mA/(V/s) == mF/cm²
    ecsa = cdl / (float(cs_uF_cm2) / 1000.0)
    return {"points": [{"scan_rate_V_s": p[0], "delta_j_half_mA_cm2": p[1]} for p in pts],
            "slope_mF_cm2": slope, "intercept": inter, "r2": r2,
            "cdl_mF_cm2": cdl, "cs_uF_cm2": float(cs_uF_cm2),
            "ecsa_cm2": ecsa, "area_cm2": float(area), "rf": ecsa / float(area)}



class PlotBackend:
    name = "base"

    def plot(self, d, out_png, opts):
        raise NotImplementedError


def prepare_xy(d, opts):
    """返回 (x, y, xlabel, ylabel)。

    - EIS：Z' vs -Z''
    - CV/LSV 且给了参比电极偏移与面积：**换算成 V vs RHE 与 mA cm⁻²**
    - 其他：原始两列
    """
    cols, rows = d["columns"], d["rows"]
    if len(cols) >= 3 and "Z'" in cols[1] and 'Z"' in cols[2]:
        return ([r[1] for r in rows], [-r[2] for r in rows], "Z' (Ω)", "-Z'' (Ω)")
    x = [r[0] for r in rows]
    y = [r[1] for r in rows]
    tech = (d["meta"].get("technique") or "").lower()
    is_cv = any(k in tech for k in ("cyclic", "voltammetry", "lsv", "linear sweep"))
    if is_cv and opts.get("eref_offset") is not None and opts.get("area"):
        off, area = float(opts["eref_offset"]), float(opts["area"])
        return ([v + off for v in x], [v * 1000.0 / area for v in y],
                "Potential (V vs RHE)", "Current Density (mA cm$^{-2}$)")
    xl = f"{cols[0]} ({d['units'][0]})" if d["units"][0] else cols[0]
    yl = f"{cols[1]} ({d['units'][1]})" if d["units"][1] else cols[1]
    return x, y, xl, yl


class MatplotlibBackend(PlotBackend):
    name = "matplotlib"

    def plot(self, d, out_png, opts):
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
        plt.rcParams["font.sans-serif"] = ["Microsoft YaHei", "SimHei", "DejaVu Sans"]
        plt.rcParams["axes.unicode_minus"] = False
        x, y, xl, yl = prepare_xy(d, opts)
        fig, ax = plt.subplots(figsize=(4.2, 3.4), dpi=300)
        ax.plot(x, y, "o-", ms=3, lw=1.2)
        ax.set_xlabel(xl)
        ax.set_ylabel(yl)
        if "Z'" in xl:
            ax.set_aspect("equal", adjustable="datalim")
        ax.set_title(os.path.splitext(os.path.basename(d["path"]))[0], fontsize=8)
        fig.tight_layout()
        fig.savefig(out_png)
        plt.close(fig)
        return out_png


ORIGIN_SKILL_DIRS = (r"E:\.claude\skills\origin-plot",
                     os.path.expanduser(r"~\.claude\skills\origin-plot"))


def find_origin_skill():
    cands = [os.environ.get("ORIGIN_PLOT_DIR")] + list(ORIGIN_SKILL_DIRS)
    for d in cands:
        if d and os.path.isfile(os.path.join(d, "scripts", "origin_plot.py")):
            return os.path.abspath(d)
    return None


def origin_recipe(d):
    tech = (d["meta"].get("technique") or "").lower()
    if "impedance" in tech:
        return "eis"
    if "linear sweep" in tech or "lsv" in tech:
        return "lsv"
    if "cyclic" in tech or "voltammetry" in tech:
        return "cv"
    return "line"


def build_origin_command(d, out_png, opts, skill_dir, csv_path):
    """构造 origin_plot.py 命令行（纯函数，便于自检）。"""
    r = origin_recipe(d)
    argv = [sys.executable, os.path.join(skill_dir, "scripts", "origin_plot.py"),
            csv_path, "--recipe", r, "-o", out_png, "--no-ask"]
    if r in ("cv", "lsv"):
        stem = os.path.splitext(os.path.basename(csv_path))[0]
        argv += ["--legend", stem]
        if opts.get("eref_label"):
            argv += ["--ref-electrode", str(opts["eref_label"])]
        if opts.get("area"):
            argv += ["--area", str(opts["area"])]
        if opts.get("ph") is not None:
            argv += ["--pH", str(opts["ph"])]
        elif opts.get("eref_offset") is not None:
            argv += ["--eshift", str(opts["eref_offset"])]
    return argv


def write_origin_csv(d, csv_path):
    """origin-plot 约定：第 1 列 X，其余列 Y。"""
    cols = d["columns"]
    units = d["units"]
    os.makedirs(os.path.dirname(csv_path), exist_ok=True)
    with open(csv_path, "w", encoding="utf-8", newline="") as f:
        w = csv.writer(f)
        w.writerow([f"{c} ({u})" if u else c for c, u in zip(cols, units)])
        for r in d["rows"]:
            w.writerow([repr(v) for v in r])
    return csv_path


class OriginPlotBackend(PlotBackend):
    name = "origin-plot"

    def plot(self, d, out_png, opts):
        import subprocess
        skill = opts.get("origin_dir") or find_origin_skill()
        if not skill:
            raise RuntimeError("未找到 origin-plot 技能目录（设 ORIGIN_PLOT_DIR 或 --origin-dir）")
        tmp_dir = os.path.join(K.VAULT, "_scratch", "origin_tmp")
        stem = os.path.splitext(os.path.basename(d["path"]))[0]
        csv_path = write_origin_csv(d, os.path.join(tmp_dir, stem + ".csv"))
        argv = build_origin_command(d, out_png, opts, skill, csv_path)
        env = dict(os.environ, PYTHONIOENCODING="utf-8")
        proc = subprocess.run(argv, cwd=skill, capture_output=True, text=True,
                              encoding="utf-8", errors="replace", timeout=900, env=env)
        if proc.returncode != 0 or not os.path.isfile(out_png):
            tail = (proc.stderr or proc.stdout or "")[-1200:]
            raise RuntimeError(f"origin-plot 失败（exit={proc.returncode}）：{tail}")
        return out_png


# ---------------------------------------------------------------- 出图前检查（CV 约定）

def check_plot_ready(d, opts):
    """返回 (ok, [缺失项])。CV/LSV 必须给参比电极与面积（库约定）。"""
    tech = (d["meta"].get("technique") or "").lower()
    is_cv = any(k in tech for k in ("cyclic", "voltammetry", "lsv", "linear sweep"))
    if not is_cv:
        return True, []
    missing = []
    if not opts.get("eref_label"):
        missing.append("--eref-label（如 Ag/AgCl）")
    if opts.get("ph") is None and opts.get("eref_offset") is None:
        missing.append("--ph（电解液 pH）或 --eref-offset（总平移量 V）")
    if not opts.get("area"):
        missing.append("--area（电极面积 cm²，用于 A→mA cm⁻²）")
    return (not missing), missing


