def _selftest():
    fails = []

    def chk(label, cond, detail=""):
        print(("  ok   " if cond else "  FAIL ") + label +
              (f"   [{detail}]" if detail and not cond else ""))
        if not cond:
            fails.append(label)

    d = parse_chi(CHI_SAMPLE)
    chk("解析：CHI 列头与单位", d and d["columns"] == ["Potential", "Current"] and
        d["units"] == ["V", "A"])
    chk("解析：CHI 参数与仪器", d and d["params"].get("Scan Rate (V/s)") == "0.01" and
        d["meta"]["instrument"] == "CHI760E")
    chk("解析：CHI 数据行", d and len(d["rows"]) == 3 and d["rows"][0][1] == -0.003625)

    e = parse_chi(EIS_SAMPLE)
    chk("解析：EIS 五列", e and len(e["columns"]) == 5 and "Z'/ohm" == e["columns"][1] + "/" + e["units"][1])
    g = parse_digisim(DIGI_SAMPLE)
    chk("解析：DIGISIM 无表头", g and g["columns"] == ["E", "I"] and len(g["rows"]) == 3)
    c = parse_csv("\ufeff" + CSV_SAMPLE)
    chk("解析：CSV 去 BOM", c and c["columns"] == ["x", "y"] and len(c["rows"]) == 3)
    chk("解析：坏行被跳过", len(parse_csv("x,y\n1,2\nabc,3\n4,5\n")["rows"]) == 2)
    mixed = parse_csv("sample,v,ok,a/b\nxx,1,False,2\nyy,2,False,3\n")
    chk("解析：CSV 文本列被排除、数值列保留",
        mixed and mixed["columns"] == ["v", "a/b"] and len(mixed["rows"]) == 2)

    st = analyze(d)
    chk("统计：点数与范围", st["n_points"] == 3 and st["columns"][0]["max"] == 0.2)
    chk("统计：x 单调段数", st["x_segments"] == 1)
    st2 = analyze(parse_csv("x,y\n1,1\n0,2\n1,3\n") or {"rows": [[1, 1], [0, 2], [1, 3]],
                                                         "columns": ["x", "y"], "units": ["", ""]})
    chk("统计：x 重复被标记", "x 有重复值" in st2["flags"])

    tmp = K.make_temp_dir(prefix="sci_da_")
    try:
        d["path"] = os.path.join(tmp, "CV.1.txt")
        p_csv, p_meta = export_processed(d, tmp)
        chk("导出：processed.csv 与 meta.json 生成",
            os.path.isfile(p_csv) and os.path.isfile(p_meta))
        meta = json.load(open(p_meta, encoding="utf-8"))
        chk("导出：meta 记录源文件与点数", meta["n_points"] == 3 and meta["format"] == "chi")

        class Fake(PlotBackend):
            name = "fake"

            def __init__(self):
                self.calls = []

            def plot(self, dd, out, opts):
                self.calls.append((dd["columns"], out, opts))
                return out

        fb = Fake()
        ok, miss = check_plot_ready(d, {"eref_label": "", "eref_offset": None, "area": None})
        chk("出图门禁：CV 缺参被拒", (not ok) and len(miss) == 3)
        ok2, _ = check_plot_ready(d, {"eref_label": "Ag/AgCl", "eref_offset": 0.197,
                                      "area": 0.196})
        chk("出图门禁：参数齐全放行", ok2)
        ok3, _ = check_plot_ready(e, {})
        chk("出图门禁：EIS 不需参比电极", ok3)
        x, y, xl, yl = prepare_xy(d, {"eref_offset": 0.9268, "area": 1.0})
        chk("换算：Hg/HgO→RHE 与 mA cm⁻²",
            abs(x[0] - 0.9268) < 1e-9 and abs(y[0] - (-3.625)) < 1e-9 and
            "RHE" in xl and "mA cm" in yl)
        chk("换算：EIS 不换算", abs(prepare_xy(e, {})[1][0] - (-0.41)) < 1e-9 and
            prepare_xy(e, {})[2].startswith("Z'"))
        fb.plot(d, os.path.join(tmp, "x.png"), {})
        chk("后端：假后端可注入", len(fb.calls) == 1)
        cmd = build_origin_command(d, "out.png",
                                   {"eref_label": "Hg/HgO", "ph": 14, "area": 1.0},
                                   "S", "in.csv")
        chk("origin 后端：CV 命令含配方/参比/pH/面积",
            "cv" in cmd and "Hg/HgO" in cmd and "--pH" in cmd and "1.0" in cmd)
        cmd2 = build_origin_command(e, "out.png", {}, "S", "in.csv")
        chk("origin 后端：EIS 走 eis 配方", "eis" in cmd2)
        cmd3 = build_origin_command(d, "out.png",
                                    {"eref_label": "Hg/HgO", "eref_offset": 0.9268,
                                     "area": 1.0}, "S", "in.csv")
        chk("origin 后端：无 pH 时用 --eshift", "--eshift" in cmd3 and "0.9268" in cmd3)
    finally:
        K.remove_temp_dir(tmp)

    scans = [(0.005, [-2.5e-5, 2.5e-5]), (0.01, [-5e-5, 5e-5])]
    res = ecsa_from_scans(scans, 60.0, 1.0, min_rates=2)
    chk("ECSA：斜率=Cdl=5 mF/cm²", abs(res["cdl_mF_cm2"] - 5.0) < 1e-9)
    chk("ECSA：ECSA=Cdl/Cs", abs(res["ecsa_cm2"] - 5.0 / 0.06) < 1e-9)
    chk("ECSA：完美线性 R²=1", abs(res["r2"] - 1.0) < 1e-9)
    try:
        ecsa_from_scans(scans, 60.0, 1.0)
        chk("ECSA：扫速<3 被拒", False)
    except SystemExit:
        chk("ECSA：扫速<3 被拒", True)

    print(f"SELFTEST {'PASSED' if not fails else 'FAILED'}: {len(fails)} failure(s)")
    return 0 if not fails else 1


# ---------------------------------------------------------------- CLI

def main(argv=None):
    ap = argparse.ArgumentParser(description="电化学数据读取/统计/导出/出图（Phase 3b v0）")
    ap.add_argument("--file", help="数据文件路径（chi/digisim/csv）")
    ap.add_argument("--stats", action="store_true", help="打印统计")
    ap.add_argument("--export", action="store_true", help="导出 processed.csv + meta.json")
    ap.add_argument("--plot", action="store_true", help="出图（CV/LSV 需参比电极与面积）")
    ap.add_argument("--backend", default="matplotlib", choices=["matplotlib", "origin-plot"])
    ap.add_argument("--eref-label", default=None, help="参比电极名，如 Ag/AgCl")
    ap.add_argument("--eref-offset", type=float, default=None,
                    help="参比电极→RHE 的换算截距（V），须用户确认")
    ap.add_argument("--area", type=float, default=None, help="电极面积 cm²")
    ap.add_argument("--ph", type=float, default=None,
                    help="电解液 pH（origin-plot CV 族换算 RHE 用）")
    ap.add_argument("--origin-dir", default=None, help="origin-plot 技能目录（默认自动探测）")
    ap.add_argument("--json", action="store_true", help="统计以 JSON 打印")
    ap.add_argument("--ecsa", action="store_true",
                    help="由多扫速 CV 计算 Cdl/ECSA（需 --files 与 --e0）")
    ap.add_argument("--files", default=None, help="ECSA 系列文件，分号分隔")
    ap.add_argument("--e0", type=float, default=None, help="取样电位（V，原始参比）")
    ap.add_argument("--tol", type=float, default=0.005, help="取样窗口 ±V（默认 0.005）")
    ap.add_argument("--cs", type=float, default=60.0, help="双电层比电容 Cs，µF/cm²（默认 60）")
    ap.add_argument("--selftest", action="store_true", help="自检（不依赖数据文件）")
    args = ap.parse_args(argv)

    if args.selftest:
        return _selftest()
    if not (args.file or args.ecsa):
        ap.print_help()
        return 1

    cfg = {"sci": {"data_analysis_dir": "projects/sci-assistant/data_analysis"}}
    p = os.path.join(K.VAULT, CONFIG_REL)
    if os.path.isfile(p):
        import yaml
        cfg = yaml.safe_load(open(p, encoding="utf-8")) or cfg

    if args.ecsa:
        files = [f for f in (args.files or "").split(";") if f.strip()]
        if not files or args.e0 is None:
            raise SystemExit("[!] --ecsa 需要 --files（分号分隔）与 --e0")
        scans, used = [], []
        for f in files:
            ds = read_dataset(f)
            nu = ds["params"].get("Scan Rate (V/s)")
            if not nu:
                raise SystemExit(f"[!] {f} 缺 Scan Rate (V/s)，无法算 Cdl")
            scans.append((float(nu), currents_at(ds["rows"], args.e0, args.tol)))
            used.append(os.path.basename(f))
        res = ecsa_from_scans(scans, args.cs, args.area or 1.0)
        res.update({"files": used, "e0": args.e0, "tol": args.tol})
        print(f"[ok] ECSA：{len(used)} 个扫速，Cdl = {res['cdl_mF_cm2']:.4f} mF cm⁻²，"
              f"R² = {res['r2']:.4f}")
        for p in res["points"]:
            print(f"     ν={p['scan_rate_V_s']:.4f} V/s  "
                  f"Δj/2={p['delta_j_half_mA_cm2']:.4f} mA cm⁻²")
        print(f"     ECSA = {res['ecsa_cm2']:.1f} cm²（Cs={res['cs_uF_cm2']:g} µF cm⁻²），"
              f"RF = {res['rf']:.1f}（几何面积 {res['area_cm2']:g} cm²）")
        if args.export:
            out = os.path.join(
                K.VAULT, (cfg.get("sci") or {}).get(
                    "data_analysis_dir", "projects/sci-assistant/data_analysis"),
                f"{datetime.date.today().isoformat()}-ECSA-recalc")
            os.makedirs(out, exist_ok=True)
            pj = os.path.join(out, "ecsa_result.json")
            with open(pj, "w", encoding="utf-8", newline="\n") as f:
                json.dump(res, f, ensure_ascii=False, indent=2)
                f.write("\n")
            print(f"[ok] 导出：{os.path.relpath(pj, K.VAULT)}")
        return 0

    d = read_dataset(args.file)
    opts = {"eref_label": args.eref_label, "eref_offset": args.eref_offset,
            "area": args.area, "ph": args.ph, "origin_dir": args.origin_dir}
    st = analyze(d)
    if args.stats or not (args.export or args.plot):
        if args.json:
            print(json.dumps({"format": d["format"], "meta": d["meta"],
                              "params": d["params"], "stats": st},
                             ensure_ascii=False, indent=2))
        else:
            print(f"[ok] {os.path.basename(d['path'])} ｜ 格式 {d['format']} ｜ "
                  f"{st['n_points']} 点")
            print(f"     仪器：{d['meta'].get('instrument') or '—'} ｜ "
                  f"技术：{d['meta'].get('technique') or '—'}")
            for c in st["columns"]:
                print(f"     {c['name']}（{c['unit'] or '—'}）："
                      f"{c['min']:.6g} … {c['max']:.6g}，均值 {c['mean']:.6g}")
            if st["flags"]:
                print(f"     ⚠️ 质量标记：{'、'.join(st['flags'])}")

    if args.export:
        out = analysis_dir(cfg, d["path"])
        p_csv, p_meta = export_processed(d, out)
        print(f"[ok] 导出：{os.path.relpath(p_csv, K.VAULT)}")
        print(f"     meta：{os.path.relpath(p_meta, K.VAULT)}")

    if args.plot:
        ok, missing = check_plot_ready(d, opts)
        if not ok:
            raise SystemExit("[!] CV/LSV 出图前必须先确认：" + "；".join(missing) +
                             "\n    （库约定：横轴 V vs RHE、纵轴 mA cm⁻²；不自行假设）")
        backend = MatplotlibBackend() if args.backend == "matplotlib" else OriginPlotBackend()
        out = analysis_dir(cfg, d["path"])
        os.makedirs(out, exist_ok=True)
        png = os.path.join(out, os.path.splitext(os.path.basename(d["path"]))[0] +
                           ("_origin.png" if args.backend == "origin-plot" else ".png"))
        backend.plot(d, png, opts)
        print(f"[ok] 出图：{os.path.relpath(png, K.VAULT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
